/* P06 interactive wireframe. Browser-only sample state; no product backend. */
'use strict';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='interviewus-p02-p06-wireframe-v1';
const fresh=()=>({name:'',practice:null,session:null,assessment:null,drafts:{},answers:[],messages:{},bookmarks:[],attendance:[],plan:false,moduleDone:[],scenario:'normal'});
let state;try{state={...fresh(),...JSON.parse(localStorage.getItem(KEY)||'{}')};}catch{state=fresh();}
let route='',resultId=null,authTab='login',workTab='answer',inputMode='text',voice={status:'idle',text:''},chatPending=false,chatInput='',shareDraft=false,chatIntent='clarify',search='',topic='all',level='all',setupMode='guided',month=10,selectedDay='',toastTimer,modalAction=null;
const labels={'cau-hoi':'Câu hỏi luyện tập','phong-van':'Phiên phỏng vấn','lo-trinh':'Lộ trình cá nhân hóa','tong-quan':'Tổng quan','dang-nhap':'Đăng nhập','dau-vao':'Kiểm tra đầu vào'};
const qbank=[
 {id:'java',topic:'Java cơ bản',level:'Intern',kind:'Kiến thức',title:'Vì sao cần cả equals() và hashCode()?',prompt:'Giải thích mối liên hệ giữa hai khái niệm khi dùng đối tượng làm khóa. Trình bày bằng lời, nêu giả định và một tình huống có thể xảy ra khi chúng không nhất quán.'},
 {id:'database',topic:'Cơ sở dữ liệu',level:'Fresher',kind:'Tình huống',title:'API chậm sau khi dữ liệu tăng',prompt:'Một API tìm kiếm trước đây chạy nhanh nhưng chậm khi số bản ghi tăng. Bạn sẽ thu thập bằng chứng nào, phân tích nguyên nhân và cân nhắc giải pháp ra sao?'},
 {id:'algorithm',topic:'Thuật toán',level:'Intern',kind:'Giải thích thuật toán',title:'Giải thích tìm kiếm nhị phân bằng lời',prompt:'Mô tả cách thu hẹp phạm vi tìm kiếm, điều kiện sử dụng và cách xử lý khi không tìm thấy. Không yêu cầu viết mã.'},
 {id:'tradeoff',topic:'Thiết kế hệ thống',level:'Fresher',kind:'Lập luận & đánh đổi',title:'Khi nào nên dùng bộ nhớ đệm?',prompt:'So sánh lợi ích độ trễ với độ mới dữ liệu và chi phí vận hành. Nêu giả định, rủi ro và kế hoạch kiểm chứng trước khi lựa chọn.'},
 {id:'oop',topic:'Java cơ bản',level:'Intern',kind:'Kiến thức',title:'Kế thừa hay kết hợp đối tượng?',prompt:'Giải thích sự khác biệt, đưa ra một tình huống lựa chọn và nêu điểm đánh đổi.'},
 {id:'transaction',topic:'Cơ sở dữ liệu',level:'Fresher',kind:'Tình huống',title:'Hai giao dịch cập nhật cùng một dữ liệu',prompt:'Phân tích rủi ro đồng thời, những giả định cần làm rõ và cách xác minh giải pháp bằng lời.'}
];
const entryItems=[{id:'mcq',type:'choice',part:'Trắc nghiệm',title:'Chỉ mục cơ sở dữ liệu thường giúp ích nhất khi nào?',options:['Mọi truy vấn đều nhanh hơn bất kể dữ liệu','Cột được lọc có tính chọn lọc phù hợp và kế hoạch truy vấn dùng được chỉ mục','Không cần xem kế hoạch thực thi'],key:1}, {...qbank[0],id:'essay',part:'Tự luận',type:'essay'}, {...qbank[1],id:'case',part:'Tình huống',type:'essay'}];
const modules=[{id:'java',title:'Kiến thức nền Java & hợp đồng đối tượng',desc:'Giải thích khái niệm, làm rõ giả định và diễn đạt có cấu trúc.',q:'java'}, {id:'database',title:'Phân tích truy vấn và chỉ mục',desc:'Thu thập bằng chứng trước khi chọn một giải pháp tối ưu.',q:'database'}, {id:'algorithm',title:'Tư duy thuật toán bằng lời',desc:'Nhận diện điều kiện áp dụng, tình huống biên và độ phức tạp.',q:'algorithm'}, {id:'tradeoff',title:'Lập luận về giải pháp và đánh đổi',desc:'So sánh lựa chọn từ giả định và bằng chứng kỹ thuật.',q:'tradeoff'}];
const icon=(name,size=18)=>{const p={book:'M4 3h6a3 3 0 0 1 3 3v15a4 4 0 0 0-4-2H4z M20 3h-4a3 3 0 0 0-3 3v15a4 4 0 0 1 4-2h3z',chat:'M4 4h16v12H9l-5 4z',arrow:'M5 12h14 M13 6l6 6-6 6',mic:'M9 4a3 3 0 0 1 6 0v7a3 3 0 0 1-6 0z M5 10v1a7 7 0 0 0 14 0v-1 M12 18v4 M8 22h8',check:'M5 12l4 4L19 6',back:'M19 12H5 M11 6l-6 6 6 6',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',star:'M12 3l3 6 6 1-4 5 1 6-6-3-6 3 1-6-4-5 6-1z'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${p[name]||p.grid}"/></svg>`;};
const btn=(text,action,extra='',classes='')=>`<button type="button" class="btn ${classes}" data-action="${action}" ${extra}>${text}</button>`;
const navbtn=(text,to,classes='')=>btn(text,'nav',`data-to="${to}"`,classes);
const pill=(text,c='')=>`<span class="pill ${c}">${esc(text)}</span>`;
const hero=(title,desc,actions='')=>`<div class="hero"><div><div class="eyebrow">interviewUS · Bản thiết kế tương tác P06</div><h1>${title}</h1><p>${desc}</p></div>${actions?`<div class="actions">${actions}</div>`:''}</div>`;
const hint=(text,type='')=>`<div class="banner ${type}">${text}</div>`;
const uid=()=>Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7);
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('Không lưu được trạng thái trình duyệt. Bạn vẫn có thể thao tác trong tab này.');}}
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.remove('hidden');toastTimer=setTimeout(()=>$('#toast').classList.add('hidden'),4200);}
function dialog(title,body,okText='',onOk=null){const d=$('#modal');if(d.open)d.close();$('#modal-title').textContent=title;$('#modal-body').innerHTML=body;$('#modal-footer').innerHTML=btn('Đóng','close-modal')+(okText?btn(okText,'modal-ok','','primary'):'');modalAction=onOk;d.showModal();}
function closeDialog(){if($('#modal').open)$('#modal').close();modalAction=null;}
function navigate(to){if(voice.status!=='idle'){dialog('Bạn còn bản ghi chưa xử lý',hint('Bản thiết kế không bật mic thật. Hãy quay lại để Dùng/Hủy bản phiên âm, hoặc xác nhận bỏ phần ghi âm mô phỏng.','error'),'Bỏ bản ghi và chuyển trang',()=>{voice={status:'idle',text:''};closeDialog();go(to);});return;}go(to);}
function go(to){resultId=null;workTab='answer';if(location.hash.slice(1)===to){route=to;render();}else location.hash=to;}
function getContext(){if(route==='phong-van'&&state.session?.status==='active'){const s=state.session;return {key:'session:'+s.id+':'+s.index,q:qbank.find(q=>q.id===s.order[s.index]),mode:s.mode,kind:'session'};}if(route==='dau-vao'&&state.assessment&&!state.assessment.submitted){const a=state.assessment;return {key:'entry:'+a.id+':'+a.index,q:entryItems[a.index],mode:'assessment',kind:'entry'};}if(route==='cau-hoi'&&state.practice){return {key:state.practice.key,q:qbank.find(q=>q.id===state.practice.qid),mode:'guided',kind:'practice'};}return null;}
function draft(ctx=getContext()){if(!ctx)return null;return state.drafts[ctx.key]||(state.drafts[ctx.key]={blocks:[{id:uid(),text:''}],choice:null,saved:false,revision:1,voice:false});}
const draftText=d=>d.blocks.map(b=>b.text).join('\n\n');
function isFilled(d){return d&&(d.choice!==null||draftText(d).trim().length>0);}
function newPractice(qid,moduleId=null){state.practice={qid,key:'practice:'+uid(),moduleId};inputMode='text';voice={status:'idle',text:''};persist();go('cau-hoi');}
function questionSetup(qid){const q=qbank.find(q=>q.id===qid);dialog('Xác nhận mục tiêu luyện tập',`<h3>${esc(q.title)}</h3><p class="muted">${esc(q.prompt)}</p>${pill(q.topic)}<div class="divider"></div><label class="field">Vị trí mục tiêu<select id="confirm-role"><option>Backend Developer</option></select></label><label class="field">Cấp độ<select id="confirm-level"><option>Intern</option><option ${q.level==='Fresher'?'selected':''}>Fresher</option></select></label>${hint('Câu hỏi và nguồn trong bản này là dữ liệu tự soạn để mô phỏng luồng, chưa phải ngân hàng câu hỏi được review. Bạn sẽ chọn Văn bản hoặc Ghi âm trong màn làm bài.')}`,'Bắt đầu luyện câu này',()=>{closeDialog();newPractice(qid);});}
function library(){const list=qbank.filter(q=>(topic==='all'||q.topic===topic)&&(level==='all'||q.level===level)&&(q.title+' '+q.topic).toLocaleLowerCase('vi').includes(search.toLocaleLowerCase('vi')));return hero('Luyện từng câu, hiểu từng vấn đề.','Chọn câu hỏi kỹ thuật, trình bày cách hiểu và đối chiếu phản hồi. Không có bài viết hoặc chạy mã.')+`<div class="grid cols"><aside class="card filters"><h3>Bộ lọc câu hỏi</h3><label class="field">Chủ đề<select data-filter="topic"><option value="all">Tất cả chủ đề</option>${[...new Set(qbank.map(q=>q.topic))].map(t=>`<option ${topic===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">Cấp độ<select data-filter="level"><option value="all">Tất cả cấp độ</option><option ${level==='Intern'?'selected':''}>Intern</option><option ${level==='Fresher'?'selected':''}>Fresher</option></select></label>${btn('Xóa bộ lọc','clear-filter','','small soft')}<div class="divider"></div><p class="muted"><small>Mỗi câu có mục tiêu, tiêu chí công khai và thông tin nguồn. Không hiển thị đáp án trước khi làm bài.</small></p></aside><section><form id="search-form" class="searchbar"><input class="input" name="query" placeholder="Tìm theo chủ đề, khái niệm hoặc tình huống…" aria-label="Tìm câu hỏi" value="${esc(search)}"><button class="btn primary" type="submit">Tìm kiếm</button></form><div class="toolbar"><span class="muted">${list.length} câu hỏi minh họa</span><span class="pill">Chỉ tự luận kỹ thuật</span></div><div class="grid two">${list.map(q=>`<article class="card question-card"><div class="tagline">${pill(q.topic)}<span class="sample-label">Nội dung mô phỏng</span></div><h3>${esc(q.title)}</h3><p>${esc(q.kind)} · ${q.level}</p><div class="actions">${btn('Luyện câu này '+icon('arrow',15),'question-detail',`data-id="${q.id}"`,'primary small')}${btn(state.bookmarks.includes(q.id)?'Đã lưu ôn tập':'Lưu ôn tập','bookmark',`data-id="${q.id}"`,'small')}</div></article>`).join('')||`<div class="card empty"><h3>Không tìm thấy câu phù hợp</h3><p>Thử đổi từ khóa hoặc xóa bộ lọc.</p>${btn('Xóa bộ lọc','clear-filter','','soft')}</div>`}</div></section></div>`;}
function setup(){return hero('Một phiên phỏng vấn, bốn góc nhìn.','Thiết lập mục tiêu trước khi bắt đầu. Chọn cách nhận phản hồi; cách nhập bằng văn bản hoặc ghi âm được chọn riêng trong phòng.')+`<div class="grid workspace"><section class="card"><h3>Chế độ phỏng vấn</h3><div class="mode-grid"><button class="mode ${setupMode==='guided'?'active':''}" data-action="mode" data-id="guided"><h3>Có hướng dẫn</h3><p>Chủ động xin gợi ý, xem phản hồi sau mỗi câu.</p></button><button class="mode ${setupMode==='simulation'?'active':''}" data-action="mode" data-id="simulation"><h3>Mô phỏng thực tế</h3><p>Chỉ hỏi rõ đề; xem báo cáo sau khi kết thúc.</p></button></div><div class="divider"></div><label class="field">Vị trí mục tiêu<select id="setup-role"><option>Backend Developer</option></select></label><label class="field">Cấp độ<select id="setup-level"><option>Intern</option><option>Fresher</option></select></label><label class="field">Chủ đề cố định cho bản minh họa</label><div class="chipset">${['Kiến thức lập trình','Tình huống kỹ thuật','Giải thích thuật toán','Lập luận & đánh đổi'].map(t=>pill(t)).join('')}</div><p class="muted"><small>4 câu · Không có đồng hồ đếm ngược bắt buộc trong wireframe này.</small></p><div class="actions right">${btn('Tiếp tục thiết lập','confirm-session','','primary')}</div></section><aside class="card"><div class="avatar">Us</div><h3 style="margin-top:15px">Trợ lý đồng hành</h3><p class="muted">Làm rõ giả định, diễn đạt theo từng luận điểm và cân nhắc điểm đánh đổi.</p>${hint('Điểm, phản hồi và phiên âm trong bản này đều theo kịch bản mẫu. Không có AI, đăng nhập thật hoặc máy chủ.')}${navbtn('Thử một câu trước','cau-hoi','soft')}</aside></div>`;}
function renderBlocks(ctx){const d=draft(ctx);return d.blocks.map((b,i)=>`<div class="editor-block"><div class="block-top"><span class="label"><span class="block-num">${i+1}</span>Luận điểm ${i+1}</span><div class="block-tools"><button data-action="move-block" data-index="${i}" data-dir="-1" aria-label="Di chuyển luận điểm ${i+1} lên" ${i===0?'disabled':''}>↑</button><button data-action="move-block" data-index="${i}" data-dir="1" aria-label="Di chuyển luận điểm ${i+1} xuống" ${i===d.blocks.length-1?'disabled':''}>↓</button><button data-action="delete-block" data-index="${i}" aria-label="Xóa luận điểm ${i+1}">Xóa</button></div></div><textarea data-block="${b.id}" aria-label="Nội dung luận điểm ${i+1}" placeholder="Giải thích ý chính, nêu giả định và bằng chứng bạn sẽ kiểm tra…">${esc(b.text)}</textarea></div>`).join('')+`<button class="add-block" data-action="add-block">+ Thêm khung luận điểm</button>`;}
function recorder(ctx){if(inputMode!=='voice')return '';const status={idle:'Sẵn sàng ghi âm mô phỏng',recording:'Đang ghi âm mô phỏng',recorded:'Đã dừng — chờ chuyển thành văn bản',transcribing:'Đang mô phỏng phiên âm…',review:'Xem và sửa bản phiên âm',error:'Chưa tạo được bản phiên âm'}[voice.status];return `<div class="recorder"><div class="rec-state"><span class="rec-dot ${voice.status==='recording'?'on':''}"></span>${status}</div><p class="muted"><small>Wireframe không bật mic và không thu âm thật. Luồng sản phẩm: xin quyền mic → ghi/dừng → xem/sửa bản phiên âm → xác nhận chèn vào bài.</small></p><div class="actions">${voice.status==='idle'?btn('Bắt đầu ghi âm','voice-start', '', 'soft'):''}${voice.status==='recording'?btn('Dừng ghi âm','voice-stop','','danger'):''}${['recorded','error'].includes(voice.status)?btn('Chuyển thành văn bản','transcribe','','primary')+btn('Nghe thử mô phỏng','listen','','soft'):''}${!['idle','transcribing'].includes(voice.status)?btn('Hủy bản ghi','voice-cancel','','small'):''}</div>${voice.status==='review'?`<label class="field" style="margin-top:15px">Bản phiên âm — có thể sửa<textarea id="transcript">${esc(voice.text)}</textarea></label><label class="field">Đưa vào<select id="voice-target"><option value="new">Thêm luận điểm mới</option>${draft(ctx).blocks.map((b,i)=>`<option value="${b.id}">Nối vào luận điểm ${i+1}</option>`).join('')}</select></label>${btn('Dùng bản phiên âm','use-transcript','','primary')}`:''}</div>`;}
function chatPanel(ctx){const messages=state.messages[ctx.key]||[];const restricted=ctx.mode==='simulation'||ctx.mode==='assessment';return `<aside class="aside card ${workTab==='answer'?'hide-mobile':''}"><div class="chat-header"><div class="avatar">Us</div><div><strong>Us-Bot · Trợ lý</strong><div class="sample-label">Phản hồi kịch bản, không phải AI thật</div></div></div><p class="chat-scope">${restricted?'Chỉ hướng dẫn thao tác và hỏi rõ đề. Không có gợi ý nội dung hoặc đáp án trước nộp.':'Hỏi rõ đề hoặc chủ động xin gợi ý định hướng. Trợ lý không viết hộ bài làm.'}</p><div class="chatlog" id="chatlog">${messages.length?messages.map(m=>`<div class="bubble ${m.role==='user'?'user':''}"><small>${m.role==='user'?'Bạn':'Us-Bot · mẫu'}</small>${esc(m.text)}</div>`).join(''):`<div class="bubble"><small>Us-Bot · mẫu</small>Bạn có thể hỏi rõ phạm vi tình huống. Gửi tin ở đây không phải nộp bài.</div>`}${chatPending?'<div class="bubble">Đang phản hồi mô phỏng…</div>':''}</div><label class="field" style="margin-top:12px">Mục đích<select id="chat-intent"><option value="clarify">Hỏi rõ đề</option><option value="hint" ${restricted?'disabled':''} ${chatIntent==='hint'&&!restricted?'selected':''}>Xin gợi ý</option></select></label><label class="check"><input id="share-draft" type="checkbox" ${shareDraft?'checked':''} ${restricted?'disabled':''}> Chủ động chia sẻ nháp hiện tại</label><div class="chatbox"><textarea id="chat-text" aria-label="Tin nhắn cho trợ lý" placeholder="Hỏi rõ yêu cầu hoặc ràng buộc…">${esc(chatInput)}</textarea><button class="btn primary" data-action="send-chat" ${chatPending?'disabled':''} aria-label="Gửi tin nhắn cho trợ lý">${icon('arrow')}</button></div><div class="chipset" style="margin-top:12px"><button class="chip" data-action="chat-chip" data-text="Tôi có thể đưa ra những giả định nào?">Làm rõ giả định</button>${!restricted?'<button class="chip" data-action="chat-chip" data-text="Cho tôi một gợi ý định hướng, chưa cần lời giải.">Xin gợi ý</button>':''}</div><p class="sample-label" style="margin-top:14px">Tin nhắn và bài nộp là hai dữ liệu riêng. Không dùng nội dung AI làm căn cứ chấm bài.</p></aside>`;}
function workspace(ctx){const d=draft(ctx);let s=state.session;let count=ctx.kind==='session'?`Câu ${s.index+1} / 4`:ctx.kind==='entry'?`Câu ${state.assessment.index+1} / 3`:'Luyện một câu';const answered=ctx.kind==='session'&&s.answers[s.index];if(answered){return hero('Đã nhận bài của câu này.','Bài đã lưu trong trạng thái demo. Chế độ mô phỏng sẽ mở phản hồi sau khi kết thúc phiên.')+hint('Bạn có thể đi tiếp hoặc kết thúc sớm. Nội dung đã nộp không thay đổi trong cùng phiên.','success')+`<div class="card"><h3>${esc(ctx.q.title)}</h3><div class="actions">${btn(s.index===3?'Xem tổng kết phiên':'Câu tiếp theo','session-next','','primary')}${btn('Kết thúc sớm','finish-session','','soft')}</div></div>`;}
const title=ctx.q.title||'Câu hỏi tự luận';return `<div class="toolbar"><div class="actions">${btn(icon('back',15)+' '+(ctx.kind==='entry'?'Bài kiểm tra đầu vào':ctx.kind==='session'?'Phiên phỏng vấn':'Thư viện'),'leave-workspace','','small ghost')}${pill(count)}${pill(ctx.kind==='session'?(s.mode==='guided'?'Có hướng dẫn':'Mô phỏng thực tế'):ctx.kind==='entry'?ctx.q.part:'Tự luận kỹ thuật')}</div><div class="actions"><span class="save-status" id="save-status">${d.saved?'Đã lưu nháp mô phỏng':'Nháp trong trình duyệt · chưa nộp'}</span>${btn('Lưu & thoát','save-exit','','small')}</div></div>${ctx.kind==='entry'?entryNavigation():''}<div class="mobile-work-tabs tabs"><button class="${workTab==='answer'?'active':''}" data-action="work-tab" data-id="answer">Bài làm</button><button class="${workTab==='chat'?'active':''}" data-action="work-tab" data-id="chat">Trợ lý</button></div><div class="grid workspace"><section class="writing ${workTab==='chat'?'hide-mobile':''}"><div class="question-prompt"><div class="eyebrow">${esc(ctx.q.part||ctx.q.kind||'Câu hỏi')}</div><h2>${esc(title)}</h2><p>${esc(ctx.q.prompt||'Chọn một phương án phù hợp nhất. Đáp án chỉ xuất hiện ở màn kết quả sau nộp.')}</p><p class="sample-label" style="margin-top:14px">Đề tự soạn để minh họa giao diện, chưa phải nội dung đã kiểm duyệt.</p></div>${ctx.q.type==='choice'?ctx.q.options.map((o,i)=>`<label class="option ${d.choice===i?'selected':''}"><input type="radio" name="entry-choice" value="${i}" ${d.choice===i?'checked':''}><span>${esc(o)}</span></label>`).join(''):`<div class="tabs"><button data-action="input-mode" data-id="text" class="${inputMode==='text'?'active':''}">Soạn văn bản</button><button data-action="input-mode" data-id="voice" class="${inputMode==='voice'?'active':''}">${icon('mic',15)} Ghi âm → văn bản</button></div>${recorder(ctx)}${renderBlocks(ctx)}`}<div class="workspace-footer"><span class="sample-label">${ctx.q.type==='choice'?'Chưa nộp: được thay đổi lựa chọn.':'Không tự nộp bản phiên âm hoặc tin chat.'}</span><div class="actions">${btn('Lưu bản nháp','save-draft','','soft')}${ctx.kind==='entry'?btn(state.assessment.index<2?'Lưu & sang câu tiếp':'Rà soát & nộp bài','entry-next','','primary'):btn('Nộp câu trả lời','submit-answer','','primary')}</div></div>${ctx.kind==='session'?`<div class="actions">${btn('Kết thúc sớm','finish-session','','small ghost')}</div>`:''}</section>${chatPanel(ctx)}</div>`;}
function answerResult(a){const q=qbank.find(q=>q.id===a.qid)||entryItems.find(q=>q.id===a.qid)||qbank[0];const failed=a.status==='failed';return hero(failed?'Bài đã lưu, phản hồi chưa sẵn sàng.':'Xem lại câu trả lời.',failed?'Đây là nhánh lỗi AI mô phỏng. Bài của bạn vẫn còn nguyên trong trình duyệt.':'Màn hình minh họa cách trình bày rubric, bài gốc và căn cứ; không đánh giá nội dung bạn vừa nhập.',btn('Quay lại','back-result','','soft'))+hint('Điểm và nhận xét dưới đây là mẫu cố định để review P06. Không được dùng làm kết quả đánh giá năng lực.','')+(failed?hint('Mô phỏng provider gặp lỗi. Chọn “Bình thường” ở thanh trên rồi thử lại.','error')+btn('Thử lại phản hồi mẫu','retry-result',`data-id="${a.id}"`,'primary'):`<div class="score-box"><div class="score-circle">Mẫu</div><div><h2>Phản hồi theo từng tiêu chí</h2><p class="muted">Các mức điểm chỉ để xem bố cục. Bản demo không có bộ chấm hay AI.</p>${pill('Đã nộp trong demo','teal')} ${pill(a.voice?'Có bản phiên âm được xác nhận':'Nhập văn bản')}</div></div>`)+`<div class="grid two"><section class="card"><h3>${esc(q.title)}</h3><p class="sample-label">Nguyên văn bài đã nộp · chỉ đọc</p><div class="original-answer">${esc(a.text)}</div></section><section class="card"><h3>Tiêu chí và căn cứ minh họa</h3>${['Kiến thức & giải thích','Phân tích tình huống','Lập luận & đánh đổi','Cấu trúc trình bày'].map((t,i)=>`<div class="rubric-row"><span>${t}</span><strong>${failed?'—':(i%2?2:3)+' / 4*'}</strong></div>`).join('')}<p class="sample-label">* Điểm mẫu cố định, chưa chấm bài.</p>${btn('Mở vị trí căn cứ minh họa','evidence',`data-id="${a.id}"`,'soft small')}</section></div><div class="actions" style="margin-top:22px">${state.session?.status==='active'&&state.session.id===a.sessionId&&state.session.answers[state.session.index]===a.id?btn('Tiếp tục phiên','continue-result',`data-id="${a.id}"`,'primary'):btn('Luyện lại câu này','repeat-answer',`data-id="${a.id}"`,'primary')}${navbtn('Mở lộ trình','lo-trinh','soft')}${navbtn('Về Tổng quan','tong-quan','soft')}</div>`;}
function sessionSummary(){const s=state.session;const count=Object.keys(s.answers).length;return hero('Tổng kết phiên phỏng vấn.',`${count} / 4 câu đã nộp trong demo. ${count<4?'Phiên kết thúc chưa đủ câu; câu chưa làm không có điểm.':'Bạn đã đi qua đủ bốn nhóm câu minh họa.'}`)+hint('Báo cáo mẫu phục vụ review giao diện. Không có điểm tổng năng lực hoặc dự đoán tuyển dụng.')+`<div class="card">${s.order.map((id,i)=>{const a=state.answers.find(a=>a.id===s.answers[i]),q=qbank.find(q=>q.id===id);return `<div class="history-row"><div><h4>${i+1}. ${q.title}</h4><p>${a?'Bài được giữ nguyên trong trạng thái demo':'Chưa trả lời · không tính 0'}</p></div>${a?btn('Xem lại','view-answer',`data-id="${a.id}"`,'small'):pill('Chưa làm','gray')}</div>`;}).join('')}</div><div class="actions" style="margin-top:22px">${btn('Tạo phiên mới','new-session','','primary')}${navbtn('Xem Tổng quan','tong-quan','soft')}${btn('In báo cáo mẫu','print','','soft')}</div>`;}
function entryNavigation(){return `<div class="card" style="margin-bottom:20px;padding:16px"><div class="toolbar" style="margin:0"><div class="assessment-nav">${entryItems.map((q,i)=>{const d=state.drafts['entry:'+state.assessment.id+':'+i];return `<button data-action="entry-index" data-index="${i}" class="${state.assessment.index===i?'current':''} ${isFilled(d)?'filled':''}">${i+1}. ${q.part}${isFilled(d)?' ✓':''}</button>`;}).join('')}</div>${btn('Rà soát nộp bài','entry-review','','small soft')}</div></div>`;}
function assessment(){if(state.assessment?.submitted)return assessmentResult();if(state.assessment)return workspace(getContext());return hero('Kiểm tra kiến thức nền tảng.','Một bộ đầu vào gồm trắc nghiệm, tự luận và tình huống. Xem lại câu chưa làm trước khi xác nhận nộp.')+`<div class="card"><h2>Ba phần, ba cách quan sát kiến thức</h2><div class="grid three">${['Trắc nghiệm — chọn một đáp án','Tự luận — giải thích bằng lời','Tình huống — phân tích & đánh đổi'].map((t,i)=>`<div><span class="block-num">${i+1}</span><h3 style="margin-top:14px">${t}</h3><p class="muted">Một câu mỗi phần trong bộ minh họa. Không có giới hạn thời gian thật.</p></div>`).join('')}</div><div class="divider"></div><label class="field">Mục tiêu<select><option>Backend Intern / Fresher</option></select></label>${hint('Trong lúc kiểm tra, trợ lý chỉ giải thích thao tác và làm rõ đề; không cho gợi ý nội dung. Ghi âm cho tự luận/tình huống chỉ mô phỏng luồng xác nhận bản phiên âm.')}${btn('Xác nhận mục tiêu & bắt đầu','start-entry','','primary')}</div>`;}
function assessmentResult(){const a=state.assessment;const complete=a.snapshot.filter(isFilled).length;return hero('Kết quả bài kiểm tra đầu vào.',`${complete} / 3 câu đã trả lời. ${complete<3?'Bài nộp thiếu — tổng điểm chưa xác định.':'Đã đủ số câu trong bộ minh họa.'}`)+hint('Trắc nghiệm có đáp án mẫu; phản hồi tự luận/tình huống là kịch bản cố định. Kết quả ở đây không phản ánh năng lực thật.')+`<div class="grid three">${entryItems.map((q,i)=>`<div class="card"><p class="eyebrow">${q.part}</p><h3>${esc(q.title)}</h3>${!isFilled(a.snapshot[i])?pill('Chưa trả lời · không tính 0','amber'):q.type==='choice'?`<p>Bạn chọn: ${esc(q.options[a.snapshot[i].choice])}</p><p class="muted">Đáp án mẫu: ${esc(q.options[q.key])}</p>${pill(a.snapshot[i].choice===q.key?'Khớp đáp án mẫu':'Chưa khớp đáp án mẫu',a.snapshot[i].choice===q.key?'teal':'amber')}`:`<p class="muted">Phản hồi mẫu: kiểm tra giả định, bằng chứng và phương án thay thế.</p>${btn('Xem bài đã nộp','entry-answer',`data-index="${i}"`,'small soft')}`}</div>`).join('')}</div><div class="actions" style="margin-top:23px">${navbtn('Xem lộ trình đề xuất','lo-trinh','primary')}${btn('Làm lại bài đầu vào','reset-entry','','soft')}${navbtn('Về Tổng quan','tong-quan','soft')}</div>`;}
function roadmap(){const has=state.assessment?.submitted;return hero('Lộ trình cá nhân hóa.','Xem phạm vi đã kiểm tra, hiểu lý do chọn mục học và bước tiếp theo. Bản này chỉ minh họa cách tổ chức kế hoạch.',has?btn(state.plan?'Đã kích hoạt trong demo':'Kích hoạt lộ trình mẫu','activate-plan','','primary'):navbtn('Kiểm tra kiến thức nền','dau-vao','primary'))+hint(has?'Có bài đầu vào trong demo. Nội dung lộ trình dưới đây là kế hoạch mẫu, chưa có thuật toán cá nhân hóa.':'Bạn chưa làm bài đầu vào. Đây là bản xem trước, chưa phải lộ trình cá nhân hóa.')+`<div class="grid cols"><aside class="card"><h3>Các chặng học</h3><div class="progress-list">${modules.map((m,i)=>`<button data-action="scroll-module" data-id="${m.id}">${i+1}. ${m.title}</button>`).join('')}</div><div class="divider"></div><p class="muted"><small>Tự đánh dấu “đã học” khác với kiến thức đã được xác minh. Không mở khóa bằng XP.</small></p>${navbtn('Xem kết quả đầu vào','dau-vao','small soft')}</aside><section class="roadmap">${modules.map((m,i)=>{const done=state.moduleDone.includes(m.id),locked=i>0&&!state.moduleDone.includes(modules[i-1].id);return `<article class="road-node ${done?'done':''} ${locked?'locked':''}" id="module-${m.id}"><div class="card"><div class="toolbar">${pill(done?'Đã đi qua trong demo':locked?'Có điều kiện tiên quyết':'Mục học tiếp theo',done?'teal':locked?'gray':'')}<small class="muted">Học liệu/tiến độ mẫu</small></div><h3>${m.title}</h3><p class="muted">${m.desc}</p><p class="sample-label">${i?'Tiên quyết minh họa: đi qua mục '+i+'.':'Mục khởi đầu cho hành trình mẫu.'} Nguồn học liệu thật cần được nhóm review.</p><div class="actions">${btn('Xem mục học','module-detail',`data-id="${m.id}"`,'soft small')}${btn(locked?'Vì sao chưa mở?':'Luyện bài liên quan',locked?'module-locked':'module-practice',`data-id="${m.id}"`,locked?'small':'primary small')}</div></div></article>`;}).join('')}</section></div>`;}
function dashboard(){const answers=state.answers;const completed=state.assessment?.submitted?1:0;return hero('Hôm nay, tiếp tục từ đâu?','Xem hoạt động đã thực hiện trong bản demo, mở bài đang dở hoặc quay lại một kết quả.',navbtn('Chọn câu để luyện','cau-hoi','primary'))+`<div class="grid three"><div class="card"><div class="stat">${answers.length}</div><div class="stat-label">Bài tự luận đã nộp trong demo</div></div><div class="card"><div class="stat">${completed}</div><div class="stat-label">Lượt kiểm tra đầu vào đã nộp</div></div><div class="card"><div class="stat">${state.moduleDone.length} / 4</div><div class="stat-label">Mục đã đi qua trong kế hoạch mẫu</div></div></div><div class="grid workspace" style="margin-top:22px"><section><div class="card"><h3>Việc hôm nay</h3>${state.practice?`<div class="history-row"><div><h4>Câu luyện tập đang dở</h4><p>Mở đúng câu và bản nháp.</p></div>${navbtn('Tiếp tục luyện câu','cau-hoi','small primary')}</div>`:''}${state.session?.status==='active'?`<div class="history-row"><div><h4>Phiên phỏng vấn đang dở</h4><p>Câu ${state.session.index+1}/4 · ${state.session.mode==='guided'?'Có hướng dẫn':'Mô phỏng'}</p></div>${navbtn('Tiếp tục phiên','phong-van','small primary')}</div>`:''}${state.assessment&&!state.assessment.submitted?`<div class="history-row"><div><h4>Bài đầu vào đang dở</h4><p>Giữ nguyên câu và bản nháp khi mở lại.</p></div>${navbtn('Tiếp tục bài','dau-vao','small primary')}</div>`:''}<div class="history-row"><div><h4>Luyện một câu hoặc học theo lộ trình</h4><p>Chọn hoạt động phù hợp với mục tiêu hôm nay.</p></div>${navbtn('Mở lộ trình','lo-trinh','small soft')}</div></div><div class="card"><div class="toolbar"><h3 style="margin:0">Bài nộp gần đây</h3>${pill('Dữ liệu trong trình duyệt')}</div>${answers.length?answers.slice().reverse().map(a=>`<div class="history-row"><div><h4>${esc((qbank.find(q=>q.id===a.qid)||{}).title||'Bài minh họa')}</h4><p>${a.voice?'Có bản phiên âm đã xác nhận':'Nhập văn bản'} · ${a.status==='failed'?'Phản hồi mẫu gặp lỗi':'Đã lưu trong demo'}</p></div><div class="actions">${btn('Xem bài','view-answer',`data-id="${a.id}"`,'small soft')}${btn('Luyện lại','repeat-answer',`data-id="${a.id}"`,'small')}</div></div>`).join(''):`<div class="empty"><h3>Chưa có bài nộp</h3><p>Hoàn thành một câu để xem luồng lịch sử.</p>${navbtn('Làm câu đầu tiên','cau-hoi','primary')}</div>`}</div></section><aside class="card"><h3>Lịch hoạt động mẫu</h3><div class="toolbar">${btn('‹','calendar-prev','','small ghost')}<strong>Tháng ${month}/2026</strong>${btn('›','calendar-next','','small ghost')}</div><div class="calendar">${['T2','T3','T4','T5','T6','T7','CN'].map(t=>`<span class="week">${t}</span>`).join('')}${Array.from({length:(new Date(2026,month-1,1).getDay()+6)%7},()=>'<span></span>').join('')}${Array.from({length:new Date(2026,month,0).getDate()},(_,i)=>{const day=`2026-${String(month).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`;return `<button data-action="calendar-day" data-id="${day}" class="${day==='2026-11-10'?'today':''} ${state.attendance.includes(day)?'checked':''} ${selectedDay===day?'selected':''}" aria-label="Ngày ${i+1} tháng ${month}">${i+1}</button>`;}).join('')}</div><p class="muted" style="margin-top:16px"><small>${selectedDay?'Đang chọn: '+selectedDay:'Ngày minh họa: 10/11/2026'}</small></p>${btn(state.attendance.includes('2026-11-10')?'Đã điểm danh mẫu':'Điểm danh hôm nay','attendance','','soft full')}<p class="sample-label" style="margin-top:10px">Điểm danh không có nghĩa đã học; không cộng XP tự động.</p></aside></div>`;}
function login(){return `<div class="auth-layout"><section class="auth-form"><div class="brand" style="margin-bottom:28px">interview<b>US</b></div><h1>${state.name?'Bạn đang trong tài khoản mẫu.':'Chào mừng bạn quay lại.'}</h1><p class="muted">Đây là bản mô phỏng đăng nhập. Không nhập mật khẩu thật.</p>${state.name?hint('Tên hiển thị: '+esc(state.name),'success')+btn('Đăng xuất mô phỏng','logout','','soft full')+`<div style="margin-top:15px">${navbtn('Về Tổng quan','tong-quan','primary full')}</div>`:`<div class="tabs"><button class="${authTab==='login'?'active':''}" data-action="auth-tab" data-id="login">Đăng nhập</button><button class="${authTab==='register'?'active':''}" data-action="auth-tab" data-id="register">Tạo tài khoản</button></div><div style="margin-top:20px">${btn('<span class="google-mark">G</span> Tiếp tục bằng Google','google','','full')}</div><div class="auth-divider">Hoặc dùng thông tin mẫu</div><form id="auth-form">${authTab==='register'?'<label class="field">Tên hiển thị<input name="displayName" autocomplete="off" placeholder="Ví dụ: An Nguyễn" required></label>':''}<label class="field">Email mẫu<input name="email" type="email" placeholder="demo@example.com" autocomplete="off" required></label><label class="field">Mật khẩu mẫu<input name="password" id="password" type="password" minlength="8" placeholder="Chỉ nhập mật khẩu giả, ít nhất 8 ký tự" autocomplete="off" required></label><div class="toolbar"><label class="check"><input type="checkbox">Ghi nhớ phiên demo</label>${btn('Hiện/ẩn','toggle-password','','small ghost')}</div>${authTab==='register'?'<label class="check"><input type="checkbox" required>Tôi hiểu đây là dữ liệu mô phỏng</label>':''}<button type="submit" class="btn primary full">${authTab==='register'?'Tạo tài khoản mẫu':'Đăng nhập mô phỏng'}</button></form><div class="actions" style="margin-top:13px">${btn('Quên mật khẩu?','password-reset','','small ghost')}${btn('Tiếp tục ẩn danh','guest','','small ghost')}</div>`}</section><section class="auth-art"><span class="pill">Luyện phỏng vấn kỹ thuật bằng tiếng Việt</span><h2 style="margin-top:24px">Luyện từng câu,<br>vững từng bước.</h2><p class="muted">Một nơi để luyện lập luận, đối chiếu bằng chứng và nhìn rõ bước học tiếp theo.</p><div class="robot" role="img" aria-label="Robot trợ lý minh họa"><div class="face"><span class="eye"></span><span class="eye"></span></div></div><div class="card"><strong>Học từ câu trả lời của chính bạn</strong><p class="muted" style="margin:8px 0 0">Văn bản hoặc bản phiên âm đã được xác nhận; phản hồi gắn với từng tiêu chí.</p></div></section></div>`;}
function render(){const current=location.hash.slice(1)||'cau-hoi';route=labels[current]?current:'cau-hoi';$('#navigation').innerHTML=Object.entries(labels).filter(([id])=>id!=='dang-nhap').map(([id,name])=>`<button data-action="nav" data-to="${id}" ${route===id?'aria-current="page"':''}>${name}</button>`).join('');$('#account').textContent=state.name?state.name:'Đăng nhập';$('#scenario').value=state.scenario;let content;if(resultId){const a=state.answers.find(a=>a.id===resultId);content=a?answerResult(a):library();}else if(route==='cau-hoi'){content=state.practice?workspace(getContext()):library();}else if(route==='phong-van'){content=state.session?(state.session.status==='active'?workspace(getContext()):sessionSummary()):setup();}else if(route==='dau-vao')content=assessment();else if(route==='lo-trinh')content=roadmap();else if(route==='tong-quan')content=dashboard();else content=login();$('#app').innerHTML=content+`<p class="footnote">interviewUS · P06 · Wireframe tương tác offline. Không phải hệ thống đã triển khai. Trạng thái chỉ nằm trong trình duyệt này.</p>`;if($('#chatlog'))$('#chatlog').scrollTop=$('#chatlog').scrollHeight;document.title=labels[route]+' · interviewUS · Demo P06';}
function saveDraft(show=true){if(state.scenario==='save-error'){toast('Mô phỏng lỗi lưu: nội dung vẫn được giữ trong trình duyệt. Chuyển tình huống sang Bình thường để thử lại.');return false;}const d=draft();if(d){d.saved=true;d.revision++;persist();if($('#save-status'))$('#save-status').textContent='Đã lưu nháp mô phỏng · chưa nộp';}if(show)toast('Đã lưu bản nháp trong trình duyệt. Chưa nộp bài.');return true;}
function pendingVoice(){return voice.status!=='idle';}
function submit(){const ctx=getContext(),d=draft(ctx);if(pendingVoice()){toast('Hãy Dùng hoặc Hủy bản phiên âm trước khi nộp.');return;}const text=draftText(d);if(!text.trim()||text.length>20000){toast('Nhập nội dung trả lời, tối đa 20.000 ký tự.');return;}if(!saveDraft(false))return;const old=state.answers.find(a=>a.context===ctx.key);if(old){resultId=old.id;render();return;}const a={id:uid(),context:ctx.key,qid:ctx.q.id,text,voice:d.voice,status:state.scenario==='ai-error'?'failed':'sample',sessionId:ctx.kind==='session'?state.session.id:null};state.answers.push(a);if(ctx.kind==='session')state.session.answers[state.session.index]=a.id;if(ctx.kind==='practice'&&state.practice.moduleId&&!state.moduleDone.includes(state.practice.moduleId))state.moduleDone.push(state.practice.moduleId);if(ctx.kind==='practice')state.practice=null;persist();if(ctx.kind==='session'&&state.session.mode==='simulation'){render();toast('Đã lưu bài trong demo. Chưa mở phản hồi giữa phiên mô phỏng.');}else{resultId=a.id;render();}}
function entryReview(){if(pendingVoice()){toast('Hãy xử lý xong bản phiên âm trước khi rà soát nộp.');return;}if(!saveDraft(false))return;const a=state.assessment;const responses=entryItems.map((_,i)=>state.drafts['entry:'+a.id+':'+i]||{blocks:[{text:''}],choice:null});const missing=responses.map((d,i)=>isFilled(d)?null:i).filter(i=>i!==null);dialog(missing.length?'Còn câu chưa hoàn thành':'Xác nhận nộp bài kiểm tra',`<p>Đã trả lời ${3-missing.length}/3 câu.</p>${missing.length?hint('Nộp thiếu giữ trạng thái “chưa trả lời”, không tự tính điểm 0. Tổng điểm chưa xác định.','error')+missing.map(i=>`<p>${btn('Làm câu '+(i+1)+' — '+entryItems[i].part,'entry-index',`data-index="${i}"`,'soft small')}</p>`).join(''):'<p>Sau khi nộp, bài chuyển sang chỉ đọc. Bản demo chỉ hiện phản hồi theo kịch bản.</p>'}`,missing.length?'Tôi hiểu, nộp phần đã làm':'Xác nhận nộp',()=>{if(state.scenario==='save-error'){toast('Mô phỏng lỗi lưu. Bài chưa được nộp.');return;}a.snapshot=JSON.parse(JSON.stringify(responses));a.submitted=true;persist();closeDialog();render();});}
async function sendChat(){const ctx=getContext();if(!ctx||chatPending)return;const input=$('#chat-text'),text=input.value.trim();if(!text||text.length>2000){toast('Tin nhắn cần có nội dung, tối đa 2.000 ký tự.');return;}const restricted=['simulation','assessment'].includes(ctx.mode);const intent=$('#chat-intent').value;const key=ctx.key;const log=state.messages[key]||(state.messages[key]=[]);log.push({role:'user',text});chatInput='';chatPending=true;persist();render();await new Promise(r=>setTimeout(r,500));let reply;if(state.scenario==='chat-error')reply='Mô phỏng chat lỗi. Bài làm không bị ảnh hưởng. Đổi về Bình thường và gửi lại câu hỏi khi cần.';else if(restricted&&(/gợi ý|đáp án|giải hộ|hint|ignore|bỏ qua/i.test(text)||intent==='hint'))reply='Trong chế độ này mình chỉ làm rõ đề và thao tác. Mình chưa cung cấp gợi ý nội dung hoặc đáp án trước khi nộp.';else if(intent==='hint')reply='Gợi ý mẫu: tách vấn đề thành giả định, bằng chứng cần thu thập và các lựa chọn. Bạn muốn giải thích bước nào trước?';else reply='Làm rõ theo kịch bản: bạn có thể nêu giả định và giải thích phạm vi áp dụng. Mọi lựa chọn kỹ thuật cần được lý giải bằng lời. Tin chat này không được tính là bài nộp.';log.push({role:'assistant',text:reply});chatPending=false;persist();if(getContext()?.key===key)render();}
const actions={
 nav:e=>navigate(e.dataset.to), 'close-modal':()=>closeDialog(),'modal-ok':()=>modalAction?.(),
 'question-detail':e=>{const q=qbank.find(q=>q.id===e.dataset.id);dialog('Chi tiết câu hỏi',`<p>${pill(q.topic)} ${pill(q.level)}</p><h2>${q.title}</h2><p>${q.prompt}</p>${hint('Tiêu chí công khai: đúng kiến thức, làm rõ giả định, lập luận và trình bày. Nguồn: câu tự soạn minh họa UI, chưa review.')}`,'Bắt đầu làm bài',()=>questionSetup(q.id));},
 bookmark:e=>{const id=e.dataset.id;state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];persist();render();toast('Đã cập nhật danh sách ôn tập mẫu.');},
 'clear-filter':()=>{search='';topic='all';level='all';render();},mode:e=>{setupMode=e.dataset.id;render();},
 'confirm-session':()=>{dialog('Xác nhận mục tiêu phiên phỏng vấn',`<p>Vị trí: Backend · Cấp độ: ${esc($('#setup-level').value)}</p><p>4 câu · ${setupMode==='guided'?'Có hướng dẫn, phản hồi từng câu':'Mô phỏng, phản hồi cuối phiên'}</p>${hint('Phương thức nhập văn bản/ghi âm chọn trong phòng. Chưa bật mic khi bắt đầu phiên.')}`,'Bắt đầu ngay',()=>{state.session={id:uid(),mode:setupMode,index:0,order:['java','database','algorithm','tradeoff'],answers:{},status:'active'};persist();closeDialog();render();});},
 'work-tab':e=>{workTab=e.dataset.id;render();},'input-mode':e=>{if(pendingVoice()&&e.dataset.id==='text'){toast('Hãy Dùng hoặc Hủy bản ghi trước khi chuyển sang Văn bản.');return;}inputMode=e.dataset.id;render();},
 'add-block':()=>{draft().blocks.push({id:uid(),text:''});persist();render();},'move-block':e=>{const d=draft(),i=+e.dataset.index,j=i+(+e.dataset.dir);if(j>=0&&j<d.blocks.length)[d.blocks[i],d.blocks[j]]=[d.blocks[j],d.blocks[i]];persist();render();},
 'delete-block':e=>{const d=draft(),i=+e.dataset.index;dialog('Xóa luận điểm này?',`<p>Nội dung trong khung ${i+1} sẽ bị bỏ khỏi bản nháp. Các luận điểm khác vẫn giữ nguyên.</p>`,'Xác nhận xóa',()=>{d.blocks.splice(i,1);if(!d.blocks.length)d.blocks.push({id:uid(),text:''});persist();closeDialog();render();});},
 'save-draft':()=>saveDraft(),'save-exit':()=>{if(pendingVoice()){toast('Hãy Dùng hoặc Hủy bản ghi trước khi lưu và thoát.');return;}if(saveDraft())go('tong-quan');},'leave-workspace':()=>{const ctx=getContext();if(pendingVoice()){toast('Còn bản ghi chưa xử lý. Hãy Dùng hoặc Hủy trước.');return;}if(ctx?.kind==='practice'){state.practice=null;persist();render();}else go('tong-quan');},
 'voice-start':()=>{if(state.scenario==='mic-denied'){toast('Mô phỏng từ chối quyền mic. Nháp vẫn giữ nguyên; bạn có thể chọn Văn bản.');return;}voice={status:'recording',text:'',context:getContext()?.key};render();},'voice-stop':()=>{voice.status='recorded';render();},'voice-cancel':()=>{voice={status:'idle',text:''};render();},listen:()=>toast('Đây là wireframe: không có bản ghi âm thật để phát.'),
 transcribe:async()=>{voice.status='transcribing';render();const ctx=getContext()?.key;await new Promise(r=>setTimeout(r,650));if(getContext()?.key!==ctx)return;if(state.scenario==='stt-error'){voice.status='error';toast('Mô phỏng phiên âm lỗi. Nháp vẫn giữ; thử lại hoặc nhập văn bản.');}else{voice={status:'review',context:ctx,text:'Tôi sẽ làm rõ giả định và phạm vi ảnh hưởng, thu thập bằng chứng rồi so sánh các phương án trước khi quyết định.'};}render();},
 'use-transcript':()=>{if(voice.context!==getContext()?.key){toast('Bản phiên âm thuộc câu khác. Hãy hủy và thu lại ở câu hiện tại.');return;}const text=$('#transcript').value.trim(),target=$('#voice-target').value;if(!text){toast('Bản phiên âm đang trống. Bạn có thể sửa hoặc hủy.');return;}const d=draft();if(target==='new')d.blocks.push({id:uid(),text});else{const b=d.blocks.find(b=>b.id===target);if(!b){toast('Luận điểm đã thay đổi. Hãy chọn nơi chèn lại.');return;}b.text+=(b.text?'\n':'')+text;}d.voice=true;d.saved=false;voice={status:'idle',text:''};inputMode='text';persist();render();toast('Đã đưa bản phiên âm vào nháp. Bài chưa được nộp.');},
 'chat-chip':e=>{chatInput=e.dataset.text;$('#chat-text').value=chatInput;$('#chat-text').focus();},'send-chat':()=>sendChat(),'submit-answer':()=>submit(),
 'retry-result':e=>{const a=state.answers.find(a=>a.id===e.dataset.id);if(state.scenario==='ai-error'){toast('Đang bật tình huống lỗi AI. Đổi về Bình thường để xem phản hồi mẫu.');return;}a.status='sample';persist();render();},
 evidence:e=>{const a=state.answers.find(a=>a.id===e.dataset.id);dialog('Vị trí căn cứ minh họa',hint('Đây chỉ là cách mở đoạn văn trong bài. Đoạn này chưa được AI xác thực hoặc dùng chấm điểm thật.')+`<div class="quote">${esc(a.text.slice(0,180))}</div><p class="muted">Bản gốc giữ nguyên; đóng hộp này để trở lại kết quả.</p>`);},
 'view-answer':e=>{const answer=state.answers.find(item=>item.id===e.dataset.id);if(!answer)return;const session=state.session;if(session?.id===answer.sessionId&&session.mode==='simulation'&&session.status==='active'){toast('Kết quả sẽ mở khi kết thúc phiên mô phỏng.');return;}resultId=answer.id;render();window.scrollTo(0,0);},'back-result':()=>{resultId=null;render();},'repeat-answer':e=>{const a=state.answers.find(a=>a.id===e.dataset.id);questionSetup(a.qid);},
 'continue-result':()=>{const answerId=resultId;resultId=null;if(state.session?.status==='active'&&state.session.answers[state.session.index]===answerId)actions['session-next']();else render();},
 'session-next':()=>{const s=state.session;if(!s.answers[s.index]){toast('Cần nộp và xác nhận lưu câu hiện tại trước.');return;}resultId=null;if(s.index<3){s.index++;voice={status:'idle',text:''};inputMode='text';}else s.status='completed';persist();render();window.scrollTo(0,0);},
 'finish-session':()=>dialog('Kết thúc phiên sớm?',`<p>Đã nộp ${Object.keys(state.session.answers).length}/4 câu. Câu chưa làm không được tính điểm 0.</p>`,'Xác nhận kết thúc',()=>{state.session.status='ended';voice={status:'idle',text:''};persist();closeDialog();render();}),
 'new-session':()=>{state.session=null;persist();render();},'start-entry':()=>{state.assessment={id:uid(),index:0,submitted:false};persist();render();},
 'entry-index':e=>{if(pendingVoice()){toast('Hãy xử lý bản phiên âm trước khi chuyển câu.');return;}closeDialog();state.assessment.index=+e.dataset.index;inputMode='text';persist();render();},
 'entry-next':()=>{if(pendingVoice()){toast('Hãy Dùng/Hủy bản phiên âm trước khi chuyển câu.');return;}if(!saveDraft(false))return;if(state.assessment.index<2){state.assessment.index++;inputMode='text';persist();render();}else entryReview();},'entry-review':()=>entryReview(),
 'entry-answer':e=>{const i=+e.dataset.index;dialog('Bài đã nộp — '+entryItems[i].part,`<div class="original-answer">${esc(draftText(state.assessment.snapshot[i]))}</div><p class="muted">Chỉ đọc. Làm lại sẽ tạo lượt mới, không sửa bản đã nộp.</p>`);},
 'reset-entry':()=>dialog('Tạo lượt kiểm tra mới?',hint('Kết quả trong wireframe sẽ chuyển sang lượt minh họa mới. Đây không phải thao tác xóa dữ liệu người học thật.'),'Tạo lượt mới',()=>{state.assessment={id:uid(),index:0,submitted:false};persist();closeDialog();render();}),
 'activate-plan':()=>{if(!state.assessment?.submitted){navigate('dau-vao');return;}dialog('Kích hoạt kế hoạch minh họa?',hint('Kế hoạch này là kịch bản P06, chưa có thuật toán cá nhân hóa hoặc xác minh năng lực.'),'Kích hoạt trong demo',()=>{state.plan=true;persist();closeDialog();render();toast('Đã kích hoạt kế hoạch mẫu.');});},
 'scroll-module':e=>document.getElementById('module-'+e.dataset.id)?.scrollIntoView({block:'center',behavior:'smooth'}),
 'module-detail':e=>{const m=modules.find(m=>m.id===e.dataset.id);dialog(m.title,`<p>${m.desc}</p>${hint('Nguồn và thời lượng đang là chỗ giữ cho thiết kế, cần nội dung đã review trước triển khai.')}<p>Thao tác học sẽ dẫn tới câu tự luận liên quan; trạng thái hoàn tất trong bản này chỉ là minh họa.</p>`,'Mở câu liên quan',()=>{closeDialog();newPractice(m.q,m.id);});},
 'module-locked':()=>dialog('Điều kiện tiên quyết',hint('Trong kế hoạch mẫu, hãy đi qua mục trước để xem cách hiển thị mở khóa. XP không quyết định quyền truy cập.')),
 'module-practice':e=>{const m=modules.find(m=>m.id===e.dataset.id);newPractice(m.q,m.id);},attendance:()=>{if(!state.attendance.includes('2026-11-10'))state.attendance.push('2026-11-10');persist();render();toast('Đã ghi nhận một lần điểm danh mẫu ngày 10/11/2026.');},
 'calendar-prev':()=>{month=month===1?12:month-1;render();},'calendar-next':()=>{month=month===12?1:month+1;render();},'calendar-day':e=>{selectedDay=e.dataset.id;render();toast('Đã chọn ngày trong lịch mẫu; không tự tạo hoạt động học.');},
 'auth-tab':e=>{authTab=e.dataset.id;render();},google:()=>dialog('Đăng nhập Google — mô phỏng',hint('Không mở Google và không gửi thông tin ra ngoài. Bấm tiếp tục để xem trạng thái tài khoản mẫu.'),'Tiếp tục bằng tài khoản mẫu',()=>{state.name='An Nguyễn';persist();closeDialog();go('tong-quan');}),guest:()=>{state.name='';persist();go('cau-hoi');toast('Đang dùng chế độ khách trong demo.');},logout:()=>{state.name='';persist();render();toast('Đã chuyển về khách trong bản demo.');},
 'toggle-password':()=>{$('#password').type=$('#password').type==='password'?'text':'password';},'password-reset':()=>dialog('Quên mật khẩu — mô phỏng','<label class="field">Email mẫu<input type="email" placeholder="demo@example.com"></label>'+hint('Không gửi email thật. Luồng sản phẩm: yêu cầu link → kiểm tra token → đặt mật khẩu mới → đăng nhập lại.'),'Xem trạng thái đã gửi link',()=>{closeDialog();toast('Màn hình mẫu: nếu tài khoản tồn tại, hệ thống sẽ gửi hướng dẫn.');}),
 print:()=>window.print(),reset:()=>dialog('Đặt lại bản demo?',hint('Chỉ xóa trạng thái demo trong trình duyệt này. Không tác động file hoặc dữ liệu thật.'),'Đặt lại',()=>{state=fresh();voice={status:'idle',text:''};resultId=null;inputMode='text';persist();closeDialog();go('cau-hoi');})
};
document.addEventListener('click', event => {
  const button = event.target.closest('[data-action]');
  if (!button) return;
  event.preventDefault();
  actions[button.dataset.action]?.(button);
});
document.addEventListener('input',e=>{if(e.target.matches('[data-block]')){const d=draft(),b=d.blocks.find(b=>b.id===e.target.dataset.block);if(b){b.text=e.target.value;d.saved=false;persist();if($('#save-status'))$('#save-status').textContent='Nháp trong trình duyệt · chưa nộp';}}if(e.target.id==='chat-text')chatInput=e.target.value;if(e.target.id==='transcript')voice.text=e.target.value;});
document.addEventListener('change',e=>{if(e.target.dataset.filter){if(e.target.dataset.filter==='topic')topic=e.target.value;else level=e.target.value;render();}if(e.target.name==='entry-choice'){draft().choice=+e.target.value;draft().saved=false;persist();render();}if(e.target.id==='scenario'){state.scenario=e.target.value;persist();toast('Đã đổi tình huống mô phỏng.');}if(e.target.id==='share-draft')shareDraft=e.target.checked;if(e.target.id==='chat-intent')chatIntent=e.target.value;});
document.addEventListener('submit',e=>{if(e.target.id==='search-form'){e.preventDefault();search=new FormData(e.target).get('query').trim();render();}if(e.target.id==='auth-form'){e.preventDefault();const f=new FormData(e.target);const name=authTab==='register'?String(f.get('displayName')).trim():'Người dùng mẫu';dialog(authTab==='register'?'Xác minh tài khoản — mẫu':'Đăng nhập — mô phỏng',hint('Không gửi email, không lưu mật khẩu và không xác thực tài khoản thật. Chỉ lưu tên hiển thị mẫu để xem chuyển trạng thái UI.'),authTab==='register'?'Mô phỏng đã xác minh':'Vào Tổng quan',()=>{state.name=name||'Người dùng mẫu';persist();closeDialog();go('tong-quan');});}});
document.addEventListener('keydown',e=>{if(e.target.id==='chat-text'&&e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendChat();}});
window.addEventListener('hashchange',()=>{resultId=null;const pendingContext=voice.context;render();if(pendingContext&&pendingContext!==getContext()?.key){voice={status:'idle',text:''};render();}window.scrollTo(0,0);});window.addEventListener('beforeunload',()=>persist());render();
